def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))

    stripe = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            stripe = ("row", r, grid[r][0])
            break
    if stripe is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                stripe = ("col", c, vals[0])
                break

    if stripe is None:
        return out

    orientation, s, stripe_color = stripe
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, stripe_color)]
    if not cells:
        return out

    if orientation == "row":
        coords = [r for r, c in cells]
        side = 1 if min(coords) > s else -1
        near = min(coords) if side == 1 else max(coords)
        shift = (s + side - near) if side == 1 else (s + side - near)
        moved = [(r + shift, c, grid[r][c]) for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for r, c, color in moved:
            if 0 <= r < h:
                out[r][c] = color
        far = max(r for r, c, _ in moved) if side == 1 else min(r for r, c, _ in moved)
        trail = far + side
        if 0 <= trail < h:
            out[trail] = [8] * w
    else:
        coords = [c for r, c in cells]
        side = 1 if min(coords) > s else -1
        near = min(coords) if side == 1 else max(coords)
        shift = s + side - near
        moved = [(r, c + shift, grid[r][c]) for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for r, c, color in moved:
            if 0 <= c < w:
                out[r][c] = color
        far = max(c for r, c, _ in moved) if side == 1 else min(c for r, c, _ in moved)
        trail = far + side
        if 0 <= trail < w:
            for r in range(h):
                out[r][trail] = 8

    return out
